import { readInvestigationResult } from '../../investigation/result.ts';
import type {
  BundleValidation,
  InvestigationDataSource,
  InvestigationRecord,
  UiFixtures,
  Unavailable,
} from './types.ts';

/**
 * The E4 data source: committed fixtures generated by `pnpm fixtures:ui` (ADR 0011). Every result
 * is checked with the contract reader before the console sees it, as results from the E6
 * application boundary will be. Operations that need that boundary (uploads, starting a run)
 * answer "unavailable" with the reason, rather than pretending to work.
 */
export const E6_REQUIRED =
  'This needs the application/API boundary planned for milestone E6. The console currently shows fixture data only.';

export class FixtureError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'FixtureError';
  }
}

export function createFixtureSource(fixtures: UiFixtures): InvestigationDataSource {
  const investigations: InvestigationRecord[] = fixtures.investigations.map((inv) => {
    const read = readInvestigationResult(inv.result);
    if (!read.ok)
      throw new FixtureError(
        `fixture ${inv.id} is not a valid investigation result: ${read.problems.map((p) => p.message).join('; ')}`,
      );
    return { ...inv, origin: 'fixture', result: read.result };
  });
  const bundles = new Map(fixtures.bundles.map((b) => [b.id, b]));

  return {
    description: { mode: 'fixture', notice: fixtures.notice },
    // Starting answers "unavailable" with its reason and the precomputed runs, so it is offered.
    getProviderStatus: () =>
      Promise.resolve({
        selected: 'fixture',
        pinned: true,
        runnable: true,
        simulated: false,
        model: null,
        models: [],
        reason: null,
      }),
    getEvidence: () => Promise.resolve({ status: 'unavailable', reason: 'fixture' }),
    getSettings: () => Promise.resolve({ provider: 'fake', ollamaModel: null, pinned: true }),
    saveSettings: () =>
      Promise.reject(new Error('Settings cannot be saved while the console shows fixtures.')),
    listInvestigations: () =>
      Promise.resolve(
        [...investigations].sort((a, b) =>
          b.result.run.startedAt.localeCompare(a.result.run.startedAt),
        ),
      ),
    getInvestigation: (id) => Promise.resolve(investigations.find((i) => i.id === id) ?? null),
    listBundles: () =>
      Promise.resolve(
        fixtures.bundles.map(({ id, label, description, origin }) => ({
          id,
          label,
          description,
          origin,
        })),
      ),
    validateBundle: (bundleId): Promise<BundleValidation> => {
      const bundle = bundles.get(bundleId);
      if (!bundle) return Promise.reject(new FixtureError(`no fixture bundle ${bundleId}`));
      return Promise.resolve({ bundleId, ...bundle.validation });
    },
    uploadBundle: (): Promise<Unavailable> =>
      Promise.resolve({ status: 'unavailable', reason: `Uploading a bundle: ${E6_REQUIRED}` }),
    startInvestigation: (bundleId) =>
      Promise.resolve({
        status: 'unavailable',
        reason: `Starting an investigation: ${E6_REQUIRED}`,
        fixtureInvestigationIds: investigations
          .filter((i) => i.bundleId === bundleId)
          .map((i) => i.id),
      }),
  };
}
